import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    mode: 'dark',
    background: {
      default: '#111',
      paper: '#181818',
    },
    primary: {
      main: '#00ff88',
      contrastText: '#111',
    },
    text: {
      primary: '#fff',
      secondary: '#00ff88',
    },
  },
  typography: {
    fontFamily: 'Montserrat, Arial, sans-serif',
    fontWeightBold: 700,
    h3: {
      fontWeight: 700,
      letterSpacing: 2,
    },
    h4: {
      fontWeight: 600,
    },
  },
  shape: {
    borderRadius: 12,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          background: 'linear-gradient(90deg, #00ff88 0%, #111 100%)',
          color: '#111',
          fontWeight: 'bold',
          boxShadow: '0 2px 12px #00ff8855',
          transition: 'background 0.2s',
          '&:hover': {
            background: 'linear-gradient(90deg, #00cc66 0%, #222 100%)',
            color: '#fff',
          },
        },
      },
    },
  },
});

export default theme;
